/**
 * @fileoverview The host's `around` hook (#714): its handler pins each function argument of the hooked call through a
 * helper of another of the host's files (`pins.mjs`), as rummage's `caller-callbacks.mjs` does.
 * @module owner-host/hooks
 */
import { pinArgs } from "./pins.mjs";

/**
 * Install the hook on `ext.b.hooked`.
 * @param {object} api - The bound api the host's `slothlet()` call returned.
 * @returns {string} The hook's id.
 */
export function installPinHook(api) {
	return api.slothlet.hook.on("ext.b.hooked:around", ({ args, next }) => next(pinArgs(api, args)), { id: "owner-host-pin" });
}
